#!/usr/bin/env python3
"""Fetch helper for the order-service reconciliation (working script, not a deliverable).

Usage:
  client.py orders  OUTDIR            fetch every orders page, save raw bodies to OUTDIR
  client.py customers OUTDIR IDS_FILE fetch the customer ids listed (one per line) in IDS_FILE
"""
import json
import os
import re
import sys
import time
import urllib.error
import urllib.request
from collections import Counter

BASE = "http://localhost:8080"
LOGPATH = "/tmp/recon/fetch.log"


def log(msg):
    line = f"{time.strftime('%H:%M:%S')} {msg}"
    print(line, flush=True)
    with open(LOGPATH, "a") as fh:
        fh.write(line + "\n")


class Client:
    def __init__(self):
        self.token = None
        self.token_fetches = 0
        self.stats = Counter()

    # ---- low level -------------------------------------------------------
    def raw(self, method, path, auth=True, timeout=30):
        headers = {}
        if auth and self.token:
            headers["Authorization"] = f"Bearer {self.token}"
        req = urllib.request.Request(
            BASE + path, method=method, headers=headers,
            data=b"" if method == "POST" else None)
        try:
            with urllib.request.urlopen(req, timeout=timeout) as resp:
                return resp.status, dict(resp.headers), resp.read()
        except urllib.error.HTTPError as err:
            return err.code, dict(err.headers), err.read()
        except (urllib.error.URLError, TimeoutError, ConnectionError, OSError) as err:
            return None, {}, repr(err).encode()

    @staticmethod
    def retry_after(headers, body):
        """Seconds the server asked us to wait (header first, then JSON body)."""
        for key, val in headers.items():
            if key.lower() == "retry-after":
                try:
                    return float(val)
                except ValueError:
                    pass
        try:
            return float(json.loads(body).get("retry_after"))
        except Exception:
            return 1.0

    # ---- token -----------------------------------------------------------
    def refresh_token(self):
        self.token = None
        while True:
            status, headers, body = self.raw("POST", "/token", auth=False)
            if status == 200:
                try:
                    tok = json.loads(body)["token"]
                except Exception:
                    log(f"token: 200 but unparseable body {body[:200]!r}; retrying")
                    time.sleep(1)
                    continue
                self.token = tok
                self.token_fetches += 1
                log(f"token: got {tok} (fetch #{self.token_fetches})")
                return
            if status == 429:
                wait = self.retry_after(headers, body)
                self.stats["429"] += 1
                log(f"token: 429, waiting {wait}s")
                time.sleep(wait + 0.05)
                continue
            log(f"token: status {status} body {body[:200]!r}; retrying in 1s")
            time.sleep(1)

    # ---- generic JSON GET with retries -----------------------------------
    def get_json(self, path, validate=None, allow_404=False):
        """GET path; repeat on any transient failure. Returns (status, data).

        status is 200, or 404 when allow_404 and the 404 was confirmed
        on three separate attempts.
        """
        attempts = 0
        notfound = 0
        consecutive_auth = 0
        while True:
            attempts += 1
            if self.token is None:
                self.refresh_token()
            status, headers, body = self.raw("GET", path)
            self.stats[str(status)] += 1
            if status == 200:
                try:
                    data = json.loads(body)
                except ValueError:
                    log(f"{path}: 200 but invalid JSON {body[:200]!r}; retrying")
                    time.sleep(0.5)
                    continue
                if validate:
                    problem = validate(data)
                    if problem:
                        log(f"{path}: 200 but bad shape ({problem}): {body[:200]!r}; retrying")
                        time.sleep(0.5)
                        continue
                return 200, data, body
            if status == 429:
                wait = self.retry_after(headers, body)
                log(f"{path}: 429 rate limited, waiting {wait}s (body {body[:120]!r})")
                time.sleep(wait + 0.05)
                continue
            if status in (401, 403):
                consecutive_auth += 1
                log(f"{path}: {status} {body[:160]!r}; fetching a new token")
                if consecutive_auth > 5:
                    time.sleep(1)
                self.refresh_token()
                continue
            consecutive_auth = 0
            if status == 404 and allow_404:
                notfound += 1
                log(f"{path}: 404 #{notfound} {body[:160]!r}")
                if notfound >= 3:
                    return 404, None, body
                time.sleep(0.5)
                continue
            # 5xx, connection problems, anything unexpected: repeat the request
            delay = min(1.0 * (1.5 ** min(attempts, 6)), 8.0)
            log(f"{path}: status {status} body {body[:200]!r} headers "
                f"{ {k: v for k, v in headers.items() if k.lower() in ('retry-after',)} }; "
                f"retrying in {delay:.1f}s")
            time.sleep(delay)


# ---- validators ------------------------------------------------------------
ORDER_KEYS = {"id", "customer_id", "status", "placed_at", "amount_cents"}


def validate_orders_page(data):
    if not isinstance(data, dict):
        return "not an object"
    for key in ("page", "total_pages", "items", "next"):
        if key not in data:
            return f"missing {key}"
    if not isinstance(data["items"], list):
        return "items not a list"
    for item in data["items"]:
        if not isinstance(item, dict) or not ORDER_KEYS <= set(item):
            return f"bad item {item!r}"
    return None


def validate_customer(data):
    if not isinstance(data, dict):
        return "not an object"
    for key in ("id", "name", "region", "tier", "discount_pct"):
        if key not in data:
            return f"missing {key}"
    return None


# ---- commands --------------------------------------------------------------
def cmd_orders(outdir):
    os.makedirs(outdir, exist_ok=True)
    cl = Client()
    page = 1
    total_pages = None
    seen = []
    while True:
        status, data, body = cl.get_json(f"/orders?page={page}", validate_orders_page)
        with open(os.path.join(outdir, f"page-{page:03d}.json"), "wb") as fh:
            fh.write(body)
        tp = data["total_pages"]
        if total_pages is None:
            total_pages = tp
        elif tp != total_pages:
            log(f"NOTE: total_pages changed {total_pages} -> {tp} at page {page}")
            total_pages = max(total_pages, tp)
        expected_next = f"/orders?page={page + 1}" if page < tp else None
        log(f"page {page}/{tp}: {len(data['items'])} items, page field {data['page']}, "
            f"next {data['next']!r}" + ("" if data["next"] == expected_next else
                                         f"  <-- expected {expected_next!r}"))
        seen.append(page)
        # follow the pages by number so one odd `next` cannot hide a page
        if page >= total_pages:
            break
        page += 1
    # What lies past the end?
    status, data, body = cl.get_json(f"/orders?page={page + 1}", None, allow_404=True)
    log(f"past-the-end probe page {page + 1}: status {status}, body {body[:200]!r}")
    log(f"done: pages {seen[0]}..{seen[-1]} ({len(seen)} pages); stats {dict(cl.stats)}; "
        f"tokens fetched {cl.token_fetches}")


def cmd_customers(outdir, ids_file):
    os.makedirs(outdir, exist_ok=True)
    cl = Client()
    ids = [ln.strip() for ln in open(ids_file) if ln.strip()]
    for cid in ids:
        dest = os.path.join(outdir, f"{cid}.json")
        if os.path.exists(dest):
            continue  # already fetched, keep it
        if not re.fullmatch(r"[A-Za-z0-9_-]+", cid):
            log(f"skipping odd customer id {cid!r}")
            continue
        status, data, body = cl.get_json(f"/customers/{cid}", validate_customer, allow_404=True)
        with open(dest, "wb") as fh:
            fh.write(body if status == 200 else json.dumps({"_status": status}).encode())
        log(f"customer {cid}: {status} {body[:140]!r}")
    log(f"done: {len(ids)} ids; stats {dict(cl.stats)}; tokens fetched {cl.token_fetches}")


if __name__ == "__main__":
    if len(sys.argv) >= 3 and sys.argv[1] == "orders":
        cmd_orders(sys.argv[2])
    elif len(sys.argv) >= 4 and sys.argv[1] == "customers":
        cmd_customers(sys.argv[2], sys.argv[3])
    else:
        print(__doc__)
        sys.exit(2)

